import AppKit

/// The Clip tab's **Motion** section (spec §4.3, road map 5's E2) — what a
/// clip does on its way in, on its way out, and all the way through.
///
/// An `extension VideoPane` in a file of its own, `VideoPane+Transition.swift`'s
/// shape, because `VideoPane.swift` is over the size cap and may not grow.
///
/// **Every write is PER CLIP.** A `motion` patch replaces the whole object
/// (`MotionProps.dictionary` always writes three keys), so one `set_video`
/// over several ids would stamp the first clip's other two slots onto every
/// other clip. Each row therefore reads THAT clip's base motion, changes the
/// one slot or field, and emits that clip's own op — through
/// `ops(video:for:)`, whose `structural` puts motion on the base props even
/// inside an action. Reset alone is selection-wide, since every clip gets the
/// same value. Reads are the first clip's, the section rule.
extension VideoPane {
    // MARK: Motion

    func motionSection() -> InspectorSection {
        let binding = self.binding
        let edges = EdgeMotion.allCases
        let durings = DuringMotion.allCases
        func motion() -> MotionProps { binding.videoProps.motion ?? MotionProps() }
        /// One op per clip over the selection's pixel clips; `step` answers
        /// the clip's next motion, or nil to skip the clip.
        func perClip(_ step: (ClipSnapshot, MotionProps) -> MotionProps?) -> [ReelOp] {
            var ops: [ReelOp] = []
            for clip in binding.videoClips {
                let current = clip.videoProps.motion ?? MotionProps()
                guard let next = step(clip, current) else { continue }
                ops.append(
                    contentsOf: binding.ops(video: VideoPatch(motion: .some(next)), for: clip))
            }
            return ops
        }
        func edgeKind(_ index: Int) -> EdgeMotion? {
            index == 0 ? nil : edges[min(max(index - 1, 0), edges.count - 1)]
        }
        /// A chosen kind keeps the slot's stored duration, else the core's
        /// own 0.5 s default (`MotionEdge()`).
        func edge(_ kind: EdgeMotion?, keeping stored: MotionEdge?) -> MotionEdge? {
            guard let kind = kind else { return nil }
            return MotionEdge(kind: kind, duration: stored?.duration ?? MotionEdge().duration)
        }
        func summary() -> String {
            let m = motion()
            var parts: [String] = []
            if let e = m.inEdge { parts.append("in " + e.displayName.lowercased()) }
            if let e = m.out { parts.append("out " + e.displayName.lowercased()) }
            if let d = m.during { parts.append(d.kind.displayName.lowercased()) }
            return parts.isEmpty ? "off" : parts.joined(separator: " · ")
        }
        func inactiveNote() -> String? {
            let selected = binding.videoClips.map { $0.videoProps.motion }
            let inactiveIn = selected.contains { $0?.inEdge.map { !$0.isActive } ?? false }
            let inactiveOut = selected.contains { $0?.out.map { !$0.isActive } ?? false }
            guard inactiveIn || inactiveOut else { return nil }
            let slots = [inactiveIn ? "In" : nil, inactiveOut ? "Out" : nil]
                .compactMap { $0 }.joined(separator: " and ")
            return "Selection includes inactive \(slots) motion (zero duration). "
                + "Increase Duration to reactivate; choose None to clear."
        }

        let preview = commandButton(
            "Preview", #selector(EditorViewController.previewClipMotion(_:)),
            toolTip:
                "Play the clip in a loop: sets the in/out range to the clip and turns Loop on"
                + " — both stay until you clear them")

        return InspectorSection(
            id: "video.motion", title: "Motion presets",
            summary: summary,
            reset: { binding.apply("Motion", video: VideoPatch(motion: .some(nil))) },
            defaultExpanded: false,
            rows: [
                InspectorNoteLabel(wraps: true, note: inactiveNote),
                inspectorPopupRow(
                    "In", binding, name: "Motion In", items: ["None"] + edges.map(\.displayName),
                    read: { motion().inEdge.map { (edges.firstIndex(of: $0.kind) ?? 0) + 1 } ?? 0 },
                    ops: { index in
                        perClip { _, m in
                            m.with { $0.inEdge = edge(edgeKind(index), keeping: m.inEdge) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.inEdge?.kind } }),
                // 0.1 s to 10 s: a few frames at the short end, and far longer
                // than any entrance is meant to take at the long one.
                inspectorValueRow(
                    "In Duration", binding, name: "Motion In Duration", unit: " s", decimals: 2,
                    min: 0.1, max: 10, quick: [0.25, 0.5, 1], slider: false,
                    read: { ReelTime.seconds(motion().inEdge?.duration ?? MotionEdge().duration) },
                    ops: { value in
                        perClip { _, m in
                            guard m.inEdge != nil else { return nil }
                            return m.with {
                                $0.inEdge?.duration = binding.frameTicks(seconds: value)
                            }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.inEdge?.duration } },
                    enabled: { motion().inEdge != nil }),
                inspectorPopupRow(
                    "Out", binding, name: "Motion Out", items: ["None"] + edges.map(\.displayName),
                    read: { motion().out.map { (edges.firstIndex(of: $0.kind) ?? 0) + 1 } ?? 0 },
                    ops: { index in
                        perClip { _, m in
                            m.with { $0.out = edge(edgeKind(index), keeping: m.out) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.out?.kind } }),
                // The same range as In Duration, for the same reason.
                inspectorValueRow(
                    "Out Duration", binding, name: "Motion Out Duration", unit: " s", decimals: 2,
                    min: 0.1, max: 10, quick: [0.25, 0.5, 1], slider: false,
                    read: { ReelTime.seconds(motion().out?.duration ?? MotionEdge().duration) },
                    ops: { value in
                        perClip { _, m in
                            guard m.out != nil else { return nil }
                            return m.with { $0.out?.duration = binding.frameTicks(seconds: value) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.out?.duration } },
                    enabled: { motion().out != nil }),
                inspectorPopupRow(
                    "During", binding, name: "Motion During",
                    items: ["None"] + durings.map(\.displayName),
                    read: {
                        motion().during.map { (durings.firstIndex(of: $0.kind) ?? 0) + 1 } ?? 0
                    },
                    ops: { index in
                        perClip { _, m in
                            guard index > 0 else { return m.with { $0.during = nil } }
                            // A kind keeps the stored amount and period, else
                            // the core's own defaults (`MotionDuring()`).
                            var during = m.during ?? MotionDuring()
                            during.kind = durings[min(index - 1, durings.count - 1)]
                            return m.with { $0.during = during }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.during?.kind } }),
                // Written as a percentage because the model's 0–1 reads as a
                // strength; `/ 100` at the write is the only conversion.
                inspectorValueRow(
                    "Amount", binding, name: "Motion Amount", unit: "%", decimals: 0,
                    min: 0, max: 100, quick: [25, 50, 75, 100], slider: false,
                    read: { (motion().during?.amount ?? MotionDuring().amount) * 100 },
                    ops: { value in
                        perClip { _, m in
                            guard m.during != nil else { return nil }
                            return m.with { $0.during?.amount = value / 100 }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.during?.amount } },
                    enabled: { motion().during != nil }),
                // 0.1 s to 10 s: a cycle shorter than a few frames aliases, and
                // one longer than ten seconds no longer reads as a cycle.
                // Disabled for drift, which ignores the period.
                inspectorValueRow(
                    "Period", binding, name: "Motion Period", unit: " s", decimals: 2,
                    min: 0.1, max: 10, quick: [0.25, 0.5, 1, 2], slider: false,
                    read: {
                        ReelTime.seconds(motion().during?.period ?? MotionDuring().period)
                    },
                    ops: { value in
                        perClip { _, m in
                            guard m.during != nil else { return nil }
                            return m.with { $0.during?.period = binding.frameTicks(seconds: value) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.during?.period } },
                    enabled: {
                        guard let d = motion().during else { return false }
                        return d.kind != .drift
                    }),
                inspectorButtonRow([preview]),
            ])
    }
}
/// `.convertFromSnakeCase` never touches these spellings.
enum EdgeMotion: String, Codable, CaseIterable {
    case fade
    case zoomIn = "zoom_in"
    case zoomOut = "zoom_out"
    case slideLeft = "slide_left"
    case slideRight = "slide_right"
    case slideUp = "slide_up"
    case slideDown = "slide_down"
    case spin
    case pop

    var displayName: String {
        switch self {
        case .fade: return "Fade"
        case .zoomIn: return "Zoom In"
        case .zoomOut: return "Zoom Out"
        case .slideLeft: return "Slide Left"
        case .slideRight: return "Slide Right"
        case .slideUp: return "Slide Up"
        case .slideDown: return "Slide Down"
        case .spin: return "Spin"
        case .pop: return "Pop"
        }
    }
}

/// The five continuous motions (`DuringMotion`). Every one is the identity
/// at clip time 0, so a clip starts exactly where it is placed whatever it
/// goes on to do. `spin` is spelled in both enums, deliberately.
enum DuringMotion: String, Codable, CaseIterable {
    case pulse
    case shake
    case spin
    case bounce
    case drift

    var displayName: String {
        switch self {
        case .pulse: return "Pulse"
        case .shake: return "Shake"
        case .spin: return "Spin"
        case .bounce: return "Bounce"
        case .drift: return "Drift"
        }
    }
}

// MARK: - Slots

/// One end of a clip: what it does, and for how long.
///
/// `duration` is a DURATION in ticks, not a time — an `in` measured forward
/// from the clip's first frame and an `out` back from its last — so
/// trimming a clip moves the preset with the edge it belongs to.
struct MotionEdge: Codable, Equatable {
    var kind: EdgeMotion
    var duration: Ticks

    /// A zero duration keeps its stored kind but has no render-time effect.
    var isActive: Bool { duration > 0 }

    var displayName: String {
        kind.displayName + (isActive ? "" : " (inactive)")
    }

    /// The title of one kind across the selected edges of one slot.
    static func menuTitle(for kind: EdgeMotion, among edges: [MotionEdge?]) -> String {
        let matching = edges.compactMap { $0 }.filter { $0.kind == kind }
        guard matching.contains(where: { !$0.isActive }) else { return kind.displayName }
        let suffix = matching.contains(where: \.isActive) ? " (some inactive)" : " (inactive)"
        },
        // On the way out a slide names the edge it leaves PAST, which is
        // the mirror of the arrival above.
        EdgeMotion::SlideLeft => Term {
            slide: Some((Side::Left, d)),
            ..Term::NONE
        },
        EdgeMotion::SlideRight => Term {
            slide: Some((Side::Right, d)),
            ..Term::NONE
        },
        EdgeMotion::SlideUp => Term {
            slide: Some((Side::Top, d)),
            ..Term::NONE
        },
        EdgeMotion::SlideDown => Term {
            slide: Some((Side::Bottom, d)),
            ..Term::NONE
        },
        EdgeMotion::Spin => Term {
            f: 1.0 - 0.7 * d,
            phi: 180.0 * d,
            o: 1.0 - d,
            ..Term::NONE
        },
        EdgeMotion::Pop => Term {
            f: back_out(left),
            o: (left / 0.25).min(1.0),
            ..Term::NONE
        },
    }
}

/// The continuous table (road map 5 §5b). Every one of the five is the
/// IDENTITY at `t = 0`, so a clip starts exactly where it is placed.
fn during(
    kind: DuringMotion,
    amount: f64,
    t: f64,
    period: f64,
    duration: f64,
    w: f64,
    h: f64,
) -> Term {
    let cycles = t / period;
    match kind {
        DuringMotion::Pulse => Term {
            f: 1.0 + 0.2 * amount * (1.0 - (std::f64::consts::TAU * cycles).cos()) / 2.0,
            ..Term::NONE
        },
        // Two incommensurable sines per axis, so the shake never repeats
        // inside a period and never reads as a loop. `m` is the SHORT edge
        // of the container, so the displacement is the same fraction of the
        // picture whatever its aspect.
        DuringMotion::Shake => {
            let m = w.min(h);
            let wave = |k: f64| (std::f64::consts::TAU * k * cycles).sin();
            Term {
                delta: (
                    0.04 * amount * m * (0.6 * wave(1.0) + 0.4 * wave(2.7)),
                    0.04 * amount * m * (0.6 * wave(1.3) + 0.4 * wave(3.1)),
                ),
                ..Term::NONE
            }
        }
        // `amount` 0.5 is one whole turn per period, which is why the total
        // is reduced `rem_euclid(360)` by the caller rather than here: the
        // reduction has to see the SUM, or an edge spin plus a during spin
        // could land on a multiple of 360 and still read as turned.
        DuringMotion::Spin => Term {
            phi: 720.0 * amount * cycles,
            ..Term::NONE
        },
        DuringMotion::Bounce => Term {
            delta: (
                0.0,
                -0.08 * amount * h * (std::f64::consts::PI * cycles).sin().abs(),
            ),
            ..Term::NONE
        },
        // The one preset that ignores `period` entirely: a drift is a slow
        // push across the WHOLE clip, so its clock is the duration.
        DuringMotion::Drift => Term {
            f: 1.0 + 0.24 * amount * t / duration,
            ..Term::NONE
        },
    }
}

/// The two edge durations after the tent rule, in ticks as floats.
fn tent(motion: &Motion, duration: f64) -> (f64, f64) {
    let raw = |edge: &Option<MotionEdge>| edge.map_or(0.0, |e| e.duration as f64);
    let (mut arrive, mut leave) = (raw(&motion.r#in), raw(&motion.out));
    if arrive + leave > duration && arrive + leave > 0.0 {
        arrive = arrive * duration / (arrive + leave);
        leave = duration - arrive;
    }
    (arrive, leave)
}

/// A `during` slot that is actually running: `period` above zero, and a
/// duration to measure a drift against.
fn live_during(motion: &Motion, duration: f64) -> Option<(MotionDuring, f64, f64)> {
    let slot = motion.during?;
    let period = slot.period as f64;
    if period <= 0.0 || !period.is_finite() {
        return None;
    }
    // A drift divides by the clip's duration; every other kind ignores it.
    if matches!(slot.kind, DuringMotion::Drift) && duration <= 0.0 {
        return None;
    }
    let amount = if slot.amount.is_finite() {
        slot.amount.clamp(0.0, 1.0)
    } else {
        0.0
    };
    Some((slot, amount, period))
}

/// `video` with its five placed fields moved by whatever `video.motion`
/// asks for at `clip_t`. Every other field is the input's.
///
/// `size` is the source's pixel size (`Project::source_size`), `None` for
/// text; `container` is the canvas the clip is placed in — the project's,
/// or the frozen canvas of the nest it lives inside. See the module doc.
pub(crate) fn apply(
    video: &VideoProps,
    clip_t: Ticks,
    duration: Ticks,
    size: Option<(f64, f64)>,

## Motion presets

A motion preset says what a clip **does** rather than where it is. Each clip has three slots: an **In** (an entrance at its start), an **Out** (an exit at its end) and a **During** (a movement for its whole length). A preset is tied to the clip's ends, so it moves with a trim. It works on any clip that draws a picture: video, still images, text, shapes, graphics and nests.

Motion is applied on top of the clip's own placement and any actions, and it is never animated by an action. A preset works relative to the clip: its scale and opacity multiply the clip's own, and its rotation and offset add to them. Zoom and Spin turn about the clip's visible centre, after any crop. The inspector fields (and `get_project`) show the clip's own, un-moved values, even though the preview and export show it moving.

### Set a preset

Use the **Motion presets** section at the end of the Clip sub-tab, or **Clip ▸ Motion ▸ In**, **Out** or **During**. Each submenu lists the kinds, then **None** to clear the slot. A checkmark shows the kind every selected clip shares.

The section's rows:

| Row | What it does | Range | Default |
|---|---|---|---|
| In | The entrance kind, or None | None and nine kinds | None |
| In Duration | How long the entrance takes (disabled with None) | 0.1–10 s (quick picks 0.25, 0.5, 1) | 0.5 s |
| Out | The exit kind, or None | None and nine kinds | None |
| Out Duration | How long the exit takes (disabled with None) | 0.1–10 s (quick picks 0.25, 0.5, 1) | 0.5 s |
| During | The continuous movement, or None | None and five kinds | None |
| Amount | How strong the During movement is (disabled with None) | 0–100% (quick picks 25, 50, 75, 100) | 50% |
| Period | How long one cycle takes (disabled with None and for Drift) | 0.1–10 s (quick picks 0.25, 0.5, 1, 2) | 1 s |
| Preview | Sets the in/out range to the clip, turns Loop on and plays it | | |

Changing a slot's kind keeps the duration, amount and period it already had. The section is closed by default, and its summary reads, for example, "in fade · out slide left · pulse", or "off". **Reset** clears all three slots. With several clips selected, each one keeps its own other slots. Preview leaves the range and Loop on until you clear them.

**Clip ▸ Motion ▸ Preview** does the same as the Preview button. With several clips selected, both loop the first selected clip that has a picture.

*Agents:* `set_video` with `motion: {in: {kind, duration}, out: {kind, duration}, during: {kind, amount, period}}` (durations and period in ticks, amount 0–1; `motion: null` clears all three).

### Entrances and exits

The same nine kinds fill both In and Out. An exit is the entrance played the other way: the In eases out as it arrives, and the Out eases in as it leaves.

| Kind | As an entrance (In) | As an exit (Out) |
|---|---|---|
| Fade | Fades in | Fades out |
| Zoom In | Grows from 60% to full size while fading in | Grows to 140% while fading out |
| Zoom Out | Shrinks from 140% to full size while fading in | Shrinks to 60% while fading out |
| Slide Left | Slides in from the right edge | Slides out past the left edge |
| Slide Right | Slides in from the left edge | Slides out past the right edge |
| Slide Up | Slides in from the bottom edge | Slides out past the top edge |
| Slide Down | Slides in from the top edge | Slides out past the bottom edge |
| Spin | Spins half a turn into place from 30% size, fading in | Spins half a turn away to 30% size, fading out |
| Pop | Springs up past full size (to about 110%) and settles, fading in over the first quarter | Swells and springs away, fading out over the last quarter |

A slide measures the layer as it is drawn, so it starts or ends exactly off the edge of the canvas (or of the nest it is inside).

### During

| Kind | What it does |
|---|---|
| Pulse | Gently grows and shrinks once per period, up to 20% larger at 100% |
| Shake | Jitters in a pattern that never visibly repeats, up to 4% of the canvas's shorter edge at 100% |
| Spin | Rotates continuously; at 50%, one full turn per period |
| Bounce | Hops upward once per period, up to 8% of the canvas height at 100% |
| Drift | A slow push-in across the whole clip, ending up to 24% larger at 100%. It ignores Period |

Every During movement starts from the clip's own placement on its first frame. It runs under the In and Out, so a clip can, for example, slide in while it pulses.

### On the timeline

A clip with an In or Out preset shows a small wedge along the bottom of its name strip, as long as the preset's duration at the current zoom. If the wedges overlap, the two presets are longer than the clip together. In that case Frame Job shortens both in proportion to their lengths, so the entrance ends on the frame where the exit begins, rather than refusing.

A clip with a During movement shows a small wave symbol at the right end of its name strip.

### Inactive presets

An In or Out with a zero duration can come from an agent or an older project. It is kept but does nothing. The section, the summary and the Motion menu mark it "(inactive)" (or "(some inactive)" across a selection), it draws no wedge, and a note reads "Selection includes inactive In motion (zero duration). Increase Duration to reactivate; choose None to clear."

### Limits

- A preset is not part of any action. Motion rows are ⊘, and edits always write the clip, even with an action selected.
- A split gives the first half no Out and the second half no In, so the cut doesn't play an exit and an entrance. A During movement restarts at each cut, so Remove Silences on a clip with Pulse or Drift can make it jump at the cuts.
- Freeze frame and Add Blurred Background drop the motion. Duplicate, Detach Audio and Paste keep it. Changing the speed doesn't rescale the presets.
- A text clip has no measured size, so a slide starts or ends half a canvas past the edge. That clears any text narrower than the canvas.
- A canvas drag started mid-motion starts from the clip's un-moved position.

## Motion blur

The Picture tab's Transform section has a **Motion Blur** row, 0–100 % (quick
values 0, 25, 50 and 100), off by default. It is the shutter as a share of one
frame: 50 % is a film camera's 180° shutter. When a clip moves — a zoom or pan
in an action, a motion preset, the nest it sits in moving — each frame shows it
blurred along the way it moved during that share of the frame. The clip's
recorded cursor is streaked along its path the same way, even when the clip
itself stands still ([The cursor](screen-recording.md#the-cursor)).

The blur is the same in the preview, in **Save Frame**, in `render_frame` and in
every export: each frame draws the clip 16 times at its positions across the
shutter and averages them. A clip that does not move in a frame draws exactly as
it does with the blur off. Motion Blur can change inside an action, so a blur
can ramp in and out.

A blended clip blends its averaged picture once: a screened clip, for example,
screens its blurred picture over what is under it.

Drawn sharp, whatever the row says:

- a clip inside a transition, and both halves of a dissolve between nests;
- a clip on a matte track, and the clips a matte cuts;
- a clip with Text Behind Subject's cut, and the person copy it draws;
- a clip with a drop shadow;
- a nest's own picture: set the blur on the clips inside it. The row is greyed
  on a nest clip and on an adjustment clip, which has no picture to move.

The cursor's click ripples stay sharp.

## Transitions

A transition plays across the **overlap** between two clips on the same track. The overlap's length is the transition's duration, and the later clip carries the transition (it is the transition *into* that clip). The overlap is drawn on the timeline as a hatched zone, with the transition's name in it when the word fits.

Two rules limit overlaps: a clip can overlap at most one neighbour on each side, and an overlap can be at most half as long as the shorter of the two clips. Clips never push each other out of the way. A move that would break either rule is refused.

### Transition styles

| Style | What it does |
|---|---|
| Cross Dissolve | The outgoing clip fades into the incoming one |
| Fade Through Black | The outgoing clip fades to black over the first half, then the incoming one fades up from black over the second half |
| Fade Through White | The same, through white (in an HLG project, the lifted SDR white) |
| Push Left | Both clips move: the outgoing leaves to the left as the incoming pushes in from the right |
| Push Right | The outgoing leaves to the right, the incoming comes in from the left |
| Push Up | The outgoing leaves upward, the incoming comes up from the bottom |
| Push Down | The outgoing leaves downward, the incoming comes down from the top |
| Wipe | An edge sweeps left to right, revealing the incoming clip |
| Wipe Left | An edge sweeps right to left |
| Wipe Up | An edge sweeps upward |
| Wipe Down | An edge sweeps downward |
| Slide | The incoming clip slides in from the right over the outgoing one, which stays put |
| Zoom | The outgoing clip grows toward you (to 125%) while the incoming one grows into place from 75%, and the two dissolve into each other |

A wipe's edge is measured in each clip's own frame, so two clips of different sizes don't meet at one line.

A fade through a colour changes the layer's own pixels toward the colour. On a clip smaller than the canvas (a picture-in-picture), the fade shows a black (or white) box over what is behind it, not a see-through fade.

### Add a transition

There are three ways:

- **Overlap two clips.** Whenever an edit makes a clip overlap the clip before it on the same track, and that clip has no transition stored, Frame Job adds a Cross Dissolve, eased (Ease In Out) and crossfading the sound. That holds whether you drag, trim an edge, paste, insert, close a gap or shift clips.
- **Clip ▸ Transition ▸ \<style\>.** Works on every selected clip at once:
  - A clip that already overlaps the clip before it gets the chosen style, keeping its curve and crossfade.
  - A clip at a **hard cut** (it starts exactly where the previous clip ends) gets a new half-second overlap, centred on the cut. The overlap is made from footage the two clips aren't showing: the source past the first clip's out point and before the second clip's in point. Nothing else on the timeline moves, and the pair's outer edges stay where they were. If there isn't half a second to spare, the transition comes out shorter.
  - A clip after a gap, or the first clip on its track, is skipped.

  A style is enabled only when at least one selected clip is at an overlap or a hard cut. The checkmark shows the first selected clip's style, or None when it has no transition. None is enabled for any selection.
- **The Transition section's Kind popup**, for a clip that already overlaps (below).

**When there is no footage to spare.** Two clips that each use their whole file have nothing beyond the cut to overlap with. Clip ▸ Transition ▸ then shows a sheet: "There's no extra footage at this cut for a transition." Choosing **Shift Clips Left** makes the overlap by sliding the second clip, and everything after it on unlocked tracks, left by half a second. The project gets that much shorter, and no clip's footage changes. Markers don't move. A clip on another track that ends up overlapping its neighbour gets a Cross Dissolve. The whole shift is one undo step. **Cancel** changes nothing.

*Agents:* `add_transition` (the hard-cut form: `kind`, `duration`, `align` `center`, `before` or `after`, and `ripple: true` for the Shift Clips Left form); `set_transition` (a kind onto a clip that already overlaps).

### The Transition section

The **Transition** section is on the Clip sub-tab when a single selected clip overlaps the clip before it. Its summary reads, for example, "cross dissolve · ease in out · 0.50 s", or "none".

| Row | What it does | Range |
|---|---|---|
| Kind | The style, or None | None and the thirteen styles |
| Curve | How the transition's progress is eased | Linear, Ease In, Ease Out, Ease In Out |
| Crossfade Audio | On: the outgoing sound fades out and the incoming fades in, eased by the Curve, in the Crossfade Shape. A pair where only one clip has sound still fades that clip. Off: both clips play at their own level across the whole overlap, mixed together. Mute, solo, ducking and volume still apply on top | On or off |
| Crossfade Shape | The curve of the crossfade, enabled while Crossfade Audio is on. **+3 dB** (constant power, the default) holds the level steady between two unrelated takes. **Linear** is a straight-line pair, which dips 3 dB in the middle of unrelated takes but suits two parts of the same sound. **S-Curve** and **−3 dB** move more of the change to the middle or the end. The incoming clip follows the shape and the outgoing clip follows it in reverse | +3 dB, Linear, S-Curve, −3 dB |
| Duration | The length of the overlap. Changing it **moves** the later clip to match | 0.02–10 s (quick picks 0.25, 0.5, 1, 2) |

A transition Frame Job makes is eased (Ease In Out) and crossfades its sound. An overlap with no stored transition draws as a linear cross dissolve with no sound crossfade, and in that state the section shows **Linear** and **Crossfade Audio** off. Setting either of them then stores a transition with exactly the values shown.

The duration is refused on a track's first clip, and past half the shorter clip. The refusal names the limit.

Two overlapping clips with no picture (audio-only clips) get the same section. Only their sound changes: Crossfade Audio and Curve control the crossfade, and Kind has no visible effect.

*Agents:* `set_transition_style` (`curve`, `audio` and `audio_shape` — `plus_3db`, `linear`, `s_curve`, `minus_3db` — each kept when absent); `set_transition_duration`.

### Remove a transition

Choose **None** in the Kind popup, or **Clip ▸ Transition ▸ None**. None is always available, because a clip can hold a transition the timeline doesn't draw: one left behind when an overlap was dragged apart, for example.

None removes the stored transition but not the overlap. While two clips still overlap they keep blending as a plain linear dissolve, with no hatch on the timeline. To get a hard cut back, move or trim the clips so they no longer overlap.

*Agents:* `set_transition` with `kind: null`.

### Limits

- A transition only plays across an overlap on one track. A transition stored on a clip that overlaps nothing does nothing until there is an overlap.
- Adjustment clips can't take a transition.
- After **Detach Audio**, Crossfade Audio on the video clips' transition has no effect, because their own sound is switched off. To crossfade the sound, overlap the detached audio clips and give them a transition of their own.
- Remove Silences and Remove Filler Words never cut into a transition's overlap. See [Remove Silences and Remove Filler Words](cleanup-tools.md).
- A layer always blends normally while it is in a transition, whatever blend mode it has.
//! `video.motion` turned into PLACEMENT — road map 5 §5b–§5c's arithmetic,
//! and the only place in the crate that reads a preset.
//!
//! A preset says what a clip DOES; this says where it therefore IS at one
//! instant. [`apply`] takes the EVALUATED video props of a clip (actions
//! already applied), the clip time, the clip's own duration, the source's
//! pixel size and the container's canvas, and answers the same props with
//! five fields moved: `scale`, `rotation`, `opacity`, `x` and `y`. Every
//! other field passes through untouched, which is what lets `recipe.rs`
//! read a layer's per-pixel properties off the moved props without knowing
//! anything about motion.
//!
//! **It is called where placement is PRODUCED and nowhere else** (spec §11,
//! R5-4): the two call sites are `recipe.rs`'s `moved` (a clip's own, which
//! `layer` and the routed dissolve's `placement` read) and `frame_of`.
//! `evaluate_clip`, `clip_state`, `get_project`, `split_clip`'s state,
//! `add_zoom_action`, `freeze_frame` and the audio plan all read the clip
//! UN-MOVED, so an edit works on the numbers a person typed and only the
//! picture moves. A build that moved `evaluate_clip` instead would pass a
//! careless render check and break every edit.
//!
//! # The three slots
//!
//! An ARRIVAL runs for the first `in` of the clip on `a = ease_out(t/in′)`,
//! a DEPARTURE for the last `out` on `d = ease_in(v)` measured back from
//! the EXCLUSIVE end so the last drawn frame still shows a sliver
//! (`recipe_text.rs:150`'s convention), and a DURING runs for the whole
//! clip. Each yields a scale factor `F`, a rotation `φ` in degrees, an
//! opacity factor `O` and an offset `Δ` in canvas pixels; the totals are
//! `F = F_in·F_out·F_during`, `φ = Σφ`, `O = O_in·O_out` and `Δ = ΣΔ`.
//!
//! **The tent.** When `in + out > D` the two are scaled to meet —
//! `in′ = in·D/(in + out)`, `out′ = D − in′` — so the arrival ends on the
//! frame the departure begins and nothing refuses. "Too long for THIS clip"
//! is a fact about a clip, not about the vocabulary, and a later trim would
//! invalidate any refusal anyway.
//!
//! **Rotation is REDUCED.** `φ` is taken `rem_euclid(360)` before it is
//! added, so a whole turn is EXACTLY no turn. Without it a rotation of 360
//! would reach Swift as `Float(360·π/180)`, whose `sin` is ~1.7e-7 rather
//! than 0 (`Compositor.swift`), and `partnerBox`'s `rotation == 0` guard
//! would read the layer as rotated. `rem_euclid` alone is not enough — it
//! adds 360 to a negative remainder and a tiny negative one ROUNDS UP to
//! exactly 360, or to a double a hair under it, and that guard compares the
//! recipe's f64 to an EXACT 0, so either one reads as rotated. So a band under
//! a whole turn is published as no turn. The band CHOSEN is "rounds to 360 as
//! an f32 of degrees", 2⁻¹⁶ of a degree: no consumer reads degrees into an f32
//! (the one f32 is the uniform above, in RADIANS), and what justifies it is
//! that it moves the corner of a 4K frame, 2202.9 px from a centred pivot, by
//! at most 5.87e-4 px (`core/tests/motion_edges.rs`).
//!
//! **The pivot is the VISIBLE centre.** The core's placement rule (★,
//! `edit_zoom.rs`) pivots on the UNCROPPED anchor, so a zoom or a spin
//! about it would make a cropped layer drift across its own preset. The
//! moved position compensates:
//! `(x, y)′ = (x, y) + s·R(θ)·c − s″·R(θ″)·c + Δ`, with `c` the cropped
//! rect's centre in source pixels, `s″` the CLAMPED drawn scale and `θ″`
//! the drawn rotation. At `F = 1`, `φ = 0` the two terms are the same
//! expression and cancel to the bit, which is what makes an inactive
//! preset free.
//!
//! **Slides are measured against the DRAWN box.** `S_right` is the offset
//! that puts the layer's right edge exactly on the container's right edge,
//! measured at `s″` and `θ″` — the size actually drawn — from the BASE
//! visible centre `p = (x, y) + s·R(θ)·c`, which is where the pivot
//! compensation holds the layer whatever the other slots do. For TEXT the
//! core has no measured size (spec §11), so `hx = W/2`, `hy = H/2` and
//! `c = 0`: the anchor starts half a canvas beyond the edge, which clears
//! any text narrower than the canvas. Recorded as a limit.
//!
//! # It never trusts the file
//!
//! `validate` range-checks no property and `evaluate_clip`'s restore copies
//! the BASE motion past `clamp_video`, so a hand-written `period: 0`, a
//! negative duration or an `amount` of 5 arrives here. A slot whose
//! duration is ≤ 0 after the tent is inactive; a `during` whose `period` is
//! ≤ 0 is inactive; `amount` is clamped to 0…1; and every output is checked
//! finite, a non-finite one leaving that field as evaluated. No NaN reaches
//! the recipe.
//!
//! **And when nothing is active it SHORT-CIRCUITS**, returning
//! `video.clone()` rather than computing an identity. `x + b − b` is not
//! `x` in floats, and the frame at `in′` has to be byte-identical to the
//! same clip with no motion at all — which is the claim `core/tests/
//! motion.rs` makes and the one an export comparison rests on.

use crate::model::{DuringMotion, EdgeMotion, Motion, MotionDuring, MotionEdge, VideoProps};
use crate::nest::rotate;
use crate::props_check::{SCALE_MAX, SCALE_MIN};
use crate::time::Ticks;

/// The overshoot curve `pop` is built on: above 1 from `u ≈ 0.37`, peaking
/// at 1.100 around `u ≈ 0.58`, back at exactly 1 when `u` is 1.
fn back_out(u: f64) -> f64 {
    let p = u - 1.0;
    1.0 + 2.70158 * p * p * p + 1.70158 * p * p
}

/// Which container edge a slide measures itself against.
#[derive(Clone, Copy)]
enum Side {
    Left,
    Right,
    Top,
    Bottom,
}

/// One slot's contribution, before the geometry a slide needs is known.
struct Term {
    f: f64,
    phi: f64,
    o: f64,
    /// A slide, as the edge it is measured from and the fraction of the way
    /// out to it — resolved once `F` and `φ` have fixed the drawn box.
    slide: Option<(Side, f64)>,
    /// A displacement in canvas pixels that needs no geometry at all.
    delta: (f64, f64),
}

impl Term {
    size: Option<(f64, f64)>,
    container: (f64, f64),
) -> VideoProps {
    let Some(motion) = video.motion else {
        return video.clone();
    };
    let t = clip_t as f64;
    let d = duration as f64;
    let (arrive, leave) = tent(&motion, d);

    let arrival_term = motion.r#in.filter(|_| arrive > 0.0 && t < arrive).map(|e| {
        let u = t / arrive;
        arrival(
            e.kind,
            crate::actions::ease(crate::model::Curve::EaseOut, u),
            u,
        )
    });
    let departure_term = motion
        .out
        .filter(|_| leave > 0.0 && t >= d - leave)
        .map(|e| {
            let v = 1.0 - (d - t) / leave;
            departure(
                e.kind,
                crate::actions::ease(crate::model::Curve::EaseIn, v),
                v,
            )
        });
    let during_term = live_during(&motion, d).map(|(slot, amount, period)| {
        during(slot.kind, amount, t, period, d, container.0, container.1)
    });

    // Nothing running: the clip is exactly where it is placed, and saying so
    // by cloning rather than by computing an identity is what makes the
    // frame byte-identical to a clip with no motion (module doc).
    if arrival_term.is_none() && departure_term.is_none() && during_term.is_none() {
        return video.clone();
    }

    let terms = [&arrival_term, &departure_term, &during_term];
    let mut factor = 1.0_f64;
    let mut phi = 0.0_f64;
    let mut opacity_factor = 1.0_f64;
    let mut delta = (0.0_f64, 0.0_f64);
    for term in terms.iter().filter_map(|t| t.as_ref()) {
        factor *= term.f;
        phi += term.phi;
        delta.0 += term.delta.0;
        delta.1 += term.delta.1;
    }
    // Opacity is the two EDGES only — a during never fades, so folding the
    // third term in would be a factor of 1 that could still round.
    for term in [&arrival_term, &departure_term]
        .iter()
        .filter_map(|t| t.as_ref())
    {
        opacity_factor *= term.o;
    }
    let phi = if phi.is_finite() {
        // `rem_euclid` alone cannot keep the reduction's promise: it is
        // `let r = self % rhs; if r < 0.0 { r + rhs.abs() } else { r }`, and
        // for a φ of −2e-14 that addition ROUNDS UP to exactly 360.0 — the
        // one value the reduction exists to prevent. An arrival `spin` one
        // tick from its end produces exactly that φ.
        let reduced = phi.rem_euclid(360.0);
        // And a double merely NEAR 360 is no better than 360 itself, because
        // `Compositor.swift`'s `partnerBox` guard tests `rotation == 0`
        // EXACTLY, on the recipe's f64 (`RecipeLayer.rotation` is a `Double`):
        // a layer that is unrotated to the eye has to publish an exact zero,
        // and the same arrival one tick earlier reaches 359.99999999999994,
        // which fails that guard exactly as 360.0 does. So a BAND under a
        // whole turn is published as no turn. The band is CHOSEN, not read off
        // a consumer: "rounds to 360 as an f32 of DEGREES", a convenient
        // conservative width of 2⁻¹⁶ of a degree (1.5259e-5°). No f32 of
        // degrees exists anywhere: the one f32 is the Metal uniform,
        // `Float(rotation · π/180)`, RADIANS, which conflates only doubles
        // within 3.64e-6° of a turn (a band 4.2× narrower) and which the guard
        // never sees. What justifies the width is the PICTURE: 1.5259e-5°
        // moves the corner of a 4K frame (√(1920² + 1080²) = 2202.9 px from
        // its centre) by at most 5.87e-4 px. What the rule actually moves is
        // 1.998e-14° one tick from an arrival's end and 1.0e-5° at the
        // `during` `core/tests/motion_edges.rs` pins.
        if reduced as f32 >= 360.0 {
            0.0
        } else {
            reduced
        }
    } else {
        0.0
    };

    let base_scale = if video.scale.is_finite() {
        video.scale
    } else {
        1.0
    };
    let base_rotation = if video.rotation.is_finite() {
        video.rotation
    } else {
        0.0
    };
    let drawn_scale = (base_scale * factor).clamp(SCALE_MIN, SCALE_MAX);
    let drawn_rotation = base_rotation + phi;

    // The cropped rect's centre in source pixels (★'s `c`), and the visible
    // size the slide box is measured from. Text has neither, so it takes the
    // half-canvas rule the module doc records as a limit.
    let crop = video.crop;
    let (centre, half_x, half_y) = match size {
        Some((sw, sh)) => {
            let visible_w = (sw - crop.l - crop.r).max(0.0);
            let visible_h = (sh - crop.t - crop.b).max(0.0);
            let k = drawn_rotation.to_radians().cos().abs();
            let n = drawn_rotation.to_radians().sin().abs();
            (
                ((crop.l - crop.r) / 2.0, (crop.t - crop.b) / 2.0),
                drawn_scale * (visible_w * k + visible_h * n) / 2.0,
                drawn_scale * (visible_w * n + visible_h * k) / 2.0,
            )
        }
        None => ((0.0, 0.0), container.0 / 2.0, container.1 / 2.0),
    };

    // The BASE visible centre — where the pivot compensation below holds the
    // layer whatever the other slots do to scale and rotation.
    let base_pivot = rotate(centre.0 * base_scale, centre.1 * base_scale, base_rotation);
    let p = (video.x + base_pivot.0, video.y + base_pivot.1);
    let side = |side: Side| match side {
        Side::Right => (container.0 / 2.0 + half_x - p.0, 0.0),
        Side::Left => (-(container.0 / 2.0 + half_x) - p.0, 0.0),
        Side::Bottom => (0.0, container.1 / 2.0 + half_y - p.1),
        Side::Top => (0.0, -(container.1 / 2.0 + half_y) - p.1),
    };
    for term in terms.iter().filter_map(|t| t.as_ref()) {
        if let Some((edge, fraction)) = term.slide {
            let (sx, sy) = side(edge);
            delta.0 += fraction * sx;
            delta.1 += fraction * sy;
        }
    }

//! Motion blur's vocabulary (format 42, spec §11 CU-110…CU-114): the one
//! sample count, `video.motion_blur`'s range check, its clamp, the clips
//! that cannot take it, and the shutter's sub-frame offsets.
//!
//! `video.motion_blur` is the shutter as a fraction of one CANVAS frame,
//! 0…1, 0 off (CU-113). The shutter is centred on the frame's instant: its
//! N samples sit at round(((2k+1−N)/(2N))·s·F) ticks from it, k = 0…N−1
//! ascending, F the canvas's frame in ticks, and its ends at ∓round(s·F/2)
//! (CU-114). One N, [`MOTION_BLUR_SAMPLES`], serves the preview,
//! `render_frame` and every export (CU-112): spike CU-S5 chose it (CU-110).
//! `recipe_blur.rs` turns the offsets into a layer's `blur` key.

use crate::model::{Clip, Source, VideoProps};
use crate::props_check::in_range;
use crate::time::{Fps, Ticks, TIMESCALE};

/// How many sub-frame placements a blurred layer is drawn at (spec §11
/// CU-110: CU-S5's N, the largest of 16, 8 and 4 within its bounds).
pub const MOTION_BLUR_SAMPLES: usize = 16;

/// `video.motion_blur`'s range (CU-113): "video.motion_blur must be between
/// 0 and 1, not 1.5".
pub(crate) fn check_motion_blur(value: f64) -> Result<(), String> {
    in_range("video.motion_blur", value, 0.0, 1.0)
}

/// An evaluated `motion_blur` brought into 0…1, NaN to 0 (an action's end is
/// checked for its keys, not its values). Never fails.
pub(crate) fn clamp_motion_blur(value: f64) -> f64 {
    if value.is_nan() {
        0.0
    } else {
        value.clamp(0.0, 1.0)
    }
}

/// `video.motion_blur` above 0 on a clip that cannot take it, refused naming
/// what the clip is (CU-111): a nest clip never draws itself (its layers are
/// its contents', each with its own blur), and an adjustment clip draws no
/// picture to move. 0 is always accepted.
pub(crate) fn check_motion_blur_clip(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if props.motion_blur <= 0.0 {
        return Ok(());
    }
    match clip.source {
        Source::Nest { .. } => Err(format!(
            "clip {} shows a nest and cannot take motion blur: set it on the clips inside",
            clip.id
        )),
        Source::Adjustment => Err(format!(
            "clip {} is an adjustment clip and cannot take motion blur",
            clip.id
        )),
        _ => Ok(()),
    }
}

/// The shutter's [`MOTION_BLUR_SAMPLES`] centred offsets from the frame's
/// instant, ascending, and its two ends, for a shutter of `shutter` frames at
/// `fps` (CU-114). F = TIMESCALE·den/num as f64; a degenerate rate has no
/// frame, so every offset is 0.
pub(crate) fn shutter_offsets(fps: Fps, shutter: f64) -> (Vec<Ticks>, (Ticks, Ticks)) {
    let frame = if fps.is_valid() {
        TIMESCALE as f64 * f64::from(fps.den) / f64::from(fps.num)
    } else {
        0.0
    };
    let span = shutter * frame;
    let n = MOTION_BLUR_SAMPLES as f64;
    let offsets = (0..MOTION_BLUR_SAMPLES)
        .map(|k| ((2.0 * k as f64 + 1.0 - n) / (2.0 * n) * span).round() as Ticks)
        .collect();
    let half = (span / 2.0).round() as Ticks;
    (offsets, (-half, half))
}
